#include <stdio.h>
#include <ctype.h>
#include <errno.h>
#include <stdlib.h>

static int read_numbers(int values[], const int maxima[], int count);

int main(void)
{
    int values[3];
    const int maxima[] = {500, 1000, 100};
    if (!read_numbers(values, maxima, 3) || values[2] == 0) {
        puts("invalid");
        return 0;
    }
    int quantity = values[0];
    int unit_cost = values[1];
    int capacity = values[2];
    int bundles = quantity / capacity;
    int loose = quantity % capacity;
    long cents = (long)quantity * unit_cost;
    printf("%d bundles, %d loose\n", bundles, loose);
    printf("%ld cents\n", cents);
    return 0;
}

static int read_numbers(int values[], const int maxima[], int count)
{
    char line[80];
    int length = 0;
    int ch;
    while ((ch = getchar()) != EOF && ch != '\n') {
        if (ch == 0 || length == (int)sizeof line - 1) { return 0; }
        line[length++] = (char)ch;
    }
    if (ferror(stdin)) { return 0; }
    line[length] = '\0';
    char *cursor = line;
    for (int i = 0; i < count; ++i) {
        char *end;
        errno = 0;
        long value = strtol(cursor, &end, 10);
        if (end == cursor || errno == ERANGE || value < 0 || value > maxima[i]) {
            return 0;
        }
        if (i + 1 < count && !isspace((unsigned char)*end)) { return 0; }
        values[i] = (int)value;
        cursor = end;
    }
    while (isspace((unsigned char)*cursor)) { ++cursor; }
    return *cursor == '\0';
}

